import{z as i,x as o,o as B,c as l,q as e,j as r,D as E,d as n,s as A,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多资产回测","description":"","frontmatter":{"title":"多资产回测","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-multiasset.md","filePath":"quant/bf-multiasset.md","lastUpdated":1791063341000}'),d={name:"quant/bf-multiasset.md"};function u(h,a,p,f,D,m){const t=o("Mermaid");return B(),l("div",null,[a[2]||(a[2]=e('<h1 id="多资产回测" tabindex="-1">多资产回测 <a class="header-anchor" href="#多资产回测" aria-label="Permalink to &quot;多资产回测&quot;">​</a></h1><div class="epigraph"><p>多资产回测里没有全局时钟：「组合在同一个瞬间行动」是工程约定；约定错了，价差与对冲的账先错。</p><footer>—— 据 Harris, Trading and Exchanges, 2003 对多市场结构与交易时段的论述；对照各交易所日历与时钟的公开规则整理</footer></div><p><a href="/quant/bf-fill-simulation-deep">上一课</a>把成交模拟拆成档位，图景还停在单一标的。组合一跨资产，时区、日历、币种、保证金、公司行动各来一套，引擎的全序与账本的记账单位都要重新设计。本课写多资产回测的框架机制：事件排序、币种换算、保证金聚合与跨市场约束；策略内容不是对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单标的回测默认三件事，跨资产后全部失效。其一，「同一时刻」存在：A股午休时芝加哥正开盘，日历、夏令时、午休各按各的表走；用一个统一时间戳列打天下，会在时段错位处制造幽灵的同时性——价差策略的一条腿在另一条腿的市场还没开盘时已经「成交」。其二，「同一记账单位」存在：美元期货盈利折回人民币用哪一刻的汇率，是账本定义的一部分；偷懒用当日收盘统一折算，跨币种的对冲账里会混进汇率择时的假损益。其三，「同一套规则」存在：T+1、涨跌停、借券可得性、保证金模型逐场所不同，写成全局假设，就在某一个市场上必然违法成交。</p><p><span class="marginnote">数字实例：A股下午 14:00（北京时间）时，芝加哥是凌晨 1:00（夏令时差 13 小时），CME 大部分时段还没开盘。若引擎用「日历日」对齐两市收盘价，一条「A股收盘买入、芝加哥收盘卖出」的所谓同时对冲，两端实际相差了整整一个全球交易日。</span></p><h3 id="排序、账本与规则各归各" tabindex="-1">排序、账本与规则各归各 <a class="header-anchor" href="#排序、账本与规则各归各" aria-label="Permalink to &quot;排序、账本与规则各归各&quot;">​</a></h3><p><strong>事件排序</strong>：每个场所维护自己的全序 \\((\\text{venue}, \\text{timestamp}, \\text{seq})\\)；跨场所声明同步策略——对价差与对冲类策略用保守水印：两条腿都到达才推进组合层决策，见<a href="/quant/late-data-recon">时钟、迟到数据与对账</a>。<strong>多币种账本</strong>：仓位按币种分列，汇率从 as-of 存储取历史标记，基准货币损益的换算时点显式声明（常用上一收盘，而不是即期逐笔）。<strong>保证金</strong>：逐场所的保证金模型可组合为组合层占用，跨市场抵扣按场所族规则，见<a href="/quant/futures-margin">保证金与盯市</a>。<strong>规则层</strong>：T+1、停牌、借券作为场所规则数据进入引擎，不写成策略 if-else，延续<a href="/quant/order-state-machine">订单状态机</a>的原则。</p>',8)),(B(),r(s,null,{default:E(()=>[A(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20VA%5B%22%E5%9C%BA%E6%89%80A%20%E5%85%A8%E5%BA%8F%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20WM%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E6%B0%B4%E5%8D%B0%20%E4%BF%9D%E5%AE%88%E5%90%8C%E6%AD%A5%22%5D%0A%20%20VB%5B%22%E5%9C%BA%E6%89%80B%20%E5%85%A8%E5%BA%8F%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20WM%0A%20%20VC%5B%22%E5%9C%BA%E6%89%80C%20%E5%85%A8%E5%BA%8F%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20WM%0A%20%20WM%20--%3E%20PB%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E5%86%B3%E7%AD%96%22%5D%0A%20%20PB%20--%3E%20OA%5B%22%E5%9C%BA%E6%89%80A%20%E8%AE%A2%E5%8D%95%E4%B8%8E%E6%92%AE%E5%90%88%22%5D%0A%20%20PB%20--%3E%20OB%5B%22%E5%9C%BA%E6%89%80B%20%E8%AE%A2%E5%8D%95%E4%B8%8E%E6%92%AE%E5%90%88%22%5D%0A%20%20OA%20--%3E%20LB%5B%22%E5%A4%9A%E5%B8%81%E7%A7%8D%E8%B4%A6%E6%9C%AC%20%E5%8E%86%E5%8F%B2%E6%B1%87%E7%8E%87%E6%A0%87%E8%AE%B0%22%5D%0A%20%20OB%20--%3E%20LB%0A%20%20LB%20--%3E%20MG%5B%22%E7%BB%84%E5%90%88%E5%B1%82%E4%BF%9D%E8%AF%81%E9%87%91%E8%81%9A%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宇宙先于事件。多资产回测的第一个数据问题是「当时有哪些可交易名字」：指数成份用 as-of 历史，见<a href="/quant/index-constituents-history">指数成分历史</a>；退市名字必须留在宇宙里，否则<a href="/quant/survivorship-bias">幸存者偏差</a>直接写进横截面。公司行动按场所接入事件流（分红、拆分、期货展期各有日历，见<a href="/quant/corporate-action-engine">公司行动引擎</a>与<a href="/quant/futures-roll-calendar">期货交割与展期日历</a>），除权日同时改仓位、订单与账本映射。流动性约束最后加：参与率上限逐场所参数化，作为撮合器拒绝订单的理由，而不是优化里的软惩罚。</p><p><span class="marginnote">水印同步的代价要诚实记账：保守策略会让组合层决策等到最慢的一条腿，等于假设你放弃快腿上的先动优势。它买到的是无前视，卖出的是实施速度——这笔交换应作为情景披露，而不是藏在引擎里。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多资产框架的核心机制是把「组合」从「一堆仓位」升级为「受约束的账本聚合」：约束在订单层（每场所规则拒绝非法单）、在组合层（保证金、敞口上限按基准货币计）、在报告层（多币种损益按声明时点折算）。三层分离后，跨市场套利的回测答案才有定义：价差收敛的每一段损益都能指认发生在哪个场所、哪种币种、哪条规则之下。同步水印则把跨场所的因果钉住：任何组合层决策引用的信息集，是所有相关场所该时刻已到达信息的交集，而不是并集——用并集就是让先开盘的市场替后开盘的市场做决定。</p><p><span class="marginnote">直觉类比：水印同步像「小组讨论必须等两人都看完材料才开始」——保守，但没人会引用别人没看过的信息。用并集像「谁先看完谁先拍板」：拍板引用了另一份还没到手的『事实』，在回测里这叫前视，在实盘里这叫做梦。</span></p><p>信息集取交集还是并集，决定价差账的合法性：</p>',7)),(B(),r(s,null,{default:E(()=>[A(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%3A%20%E7%BB%84%E5%90%88%E5%B1%82%E5%86%B3%E7%AD%96%E8%83%BD%E5%BC%95%E7%94%A8%E5%93%AA%E4%BA%9B%E4%BF%A1%E6%81%AF%3F%22%5D%20--%3E%20U%5B%22%E5%B9%B6%E9%9B%86%3A%20%E4%BB%BB%E4%B8%80%E5%9C%BA%E6%89%80%E5%B7%B2%E5%88%B0%E5%8D%B3%E7%94%A8%22%5D%0A%20%20Q%20--%3E%20I%5B%22%E4%BA%A4%E9%9B%86%3A%20%E7%9B%B8%E5%85%B3%E5%9C%BA%E6%89%80%E9%83%BD%E5%88%B0%E6%89%8D%E7%94%A8%22%5D%0A%20%20U%20--%3E%20G%5B%22%E5%B9%BD%E7%81%B5%E5%90%8C%E6%97%B6%E6%80%A7%22%5D%0A%20%20G%20--%3E%20P1%5B%22%E5%BF%AB%E8%85%BF%E5%85%88%E6%88%90%E4%BA%A4%2C%20%E6%85%A2%E8%85%BF%E8%BF%98%E6%B2%A1%E5%BC%80%E7%9B%98%22%5D%0A%20%20P1%20--%3E%20R1%5B%22%E4%BB%B7%E5%B7%AE%E8%B4%A6%E6%B7%B7%E8%BF%9B%E4%B8%8D%E5%8F%AF%E8%83%BD%E7%9A%84%E6%88%90%E4%BA%A4%22%5D%0A%20%20I%20--%3E%20WM%5B%22%E4%BF%9D%E5%AE%88%E6%B0%B4%E5%8D%B0%3A%20%E4%B8%A4%E6%9D%A1%E8%85%BF%E9%83%BD%E5%88%B0%E8%BE%BE%E6%89%8D%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20WM%20--%3E%20R2%5B%22%E6%97%A0%E5%89%8D%E8%A7%86%2C%20%E4%BD%86%E5%86%B3%E7%AD%96%E7%AD%89%E6%9C%80%E6%85%A2%E7%9A%84%E8%85%BF%22%5D%0A%20%20R2%20--%3E%20T%5B%22%E4%BB%98%E5%87%BA%3A%20%E6%94%BE%E5%BC%83%E5%BF%AB%E8%85%BF%E4%B8%8A%E7%9A%84%E5%85%88%E5%8A%A8%E4%BC%98%E5%8A%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不假装多场所微观结构可以等保真度回放：跨场所延迟、各自的数据档位差异，都应写成情景。跨场所套利对延迟假设最敏感，没有把托管与网络建模进去就谈延迟套利，是<a href="/quant/market-fragmentation">市场分割与 NBBO</a> 与<a href="/quant/low-latency-engineering">低延迟工程：内核旁路与 FPGA</a> 层面的自欺。加密日历与证券日历不共享假期，报告层要显式处理「某场所无此日」。最后，多资产放大的是账本复杂度而不是 alpha：框架保证账算得对，不保证配得好。</p><p><span class="marginnote">常见误区：初学者容易以为「多币种回测只要乘个汇率就行」。乘哪一个时点的汇率本身就是建模决定：用当日收盘统一折算，等于假设自己能在收盘瞬间以中间价换汇；用 as-of 历史汇率按声明时点折算才经得起对账。汇率择时的假损益，就是从「乘哪个价」这个细节里漏进来的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨资产三件失效的默认：同时性、记账单位、统一规则；每件都要在框架里显式重建。</li><li>排序按场所全序加组合层保守水印；决策信息集取交集，不取并集。</li><li>多币种账本用历史汇率在声明时点折算；保证金按场所族聚合为组合层占用。</li><li>宇宙、公司行动、场所规则全部 as-of 化、数据化；幸存者偏差从宇宙层挡住。</li><li>出处：Harris, <em>Trading and Exchanges</em>, 2003；站内<a href="/quant/late-data-recon">时钟、迟到数据与对账</a>、<a href="/quant/futures-margin">保证金与盯市</a>、<a href="/quant/index-constituents-history">指数成分历史</a>、<a href="/quant/survivorship-bias">幸存者偏差</a>各课。</li></ul>',5))])}const q=i(d,[["render",u]]);export{_ as __pageData,q as default};
